/* Crucible HLS light — 媒体预览辅助（§8：视频 mp4/m3u8、音频、PDF 预览）。
 * 设计取舍：不打包完整 hls.js（约 400KB）；m3u8 优先走浏览器原生 HLS（Safari /
 * Edge 扩展），不支持时解析 VOD 播放列表给出分片信息与引导，避免引 第三方 CDN 脚本。 */
(function (global) {
  "use strict";
  function canNativeHls(video) {
    if (!video || !video.canPlayType) return false;
    return (
      video.canPlayType("application/vnd.apple.mpegurl") !== "" ||
      video.canPlayType("application/x-mpegURL") !== ""
    );
  }
  function fmtPlaylist(text) {
    const lines = text.split(/\r?\n/).map(function (s) { return s.trim(); }).filter(Boolean);
    if (!lines.length || lines[0].indexOf("#EXTM3U") !== 0) return null;
    const isMaster = lines.some(function (l) { return l.indexOf("#EXT-X-STREAM-INF") === 0; });
    const segs = lines.filter(function (l) { return l.charAt(0) !== "#"; });
    return { isMaster: isMaster, segments: segs };
  }
  /* kind: "video" | "hls"；url 为站点直链（file_open=preview 保证 inline）。 */
  function attach(video, url, kind) {
    if (kind === "hls" && !canNativeHls(video)) {
      // 仍先尝试直接喂给 video（部分环境可用），error 后回退为播放列表摘要。
      let fallbackDone = false;
      video.addEventListener("error", function () {
        if (fallbackDone) return;
        fallbackDone = true;
        fetch(url)
          .then(function (r) { if (!r.ok) throw new Error("HTTP " + r.status); return r.text(); })
          .then(function (text) {
            const p = fmtPlaylist(text);
            if (!p) throw new Error("不是合法的 M3U8 播放列表");
            const tip = p.isMaster
              ? "主播放列表，包含 " + p.segments.length + " 个变体流。"
              : "媒体播放列表，包含 " + p.segments.length + " 个分片。";
            const note = "当前浏览器不支持原生 HLS；可在 Safari 打开站点 URL 播放，或下载后本地播放。";
            const holder = document.createElement("div");
            holder.className = "hint";
            holder.textContent = "HLS: " + tip + " " + note;
            if (video.parentNode) video.parentNode.replaceChild(holder, video);
          })
          .catch(function (e) {
            const holder = document.createElement("div");
            holder.className = "hint";
            holder.textContent = "HLS 预览失败: " + e.message + "。可直接打开站点 URL。";
            if (video.parentNode) video.parentNode.replaceChild(holder, video);
          });
      });
      video.src = url;
      return;
    }
    video.src = url;
  }
  global.CrucibleMedia = { attach: attach, canNativeHls: canNativeHls, fmtPlaylist: fmtPlaylist };
})(window);
